Menu.setApplicationMenu(menu);

app.whenReady().then(async () => {
  globalShortcut.register("F5", () => {
    console.log("F5 blocked – ye POS hai, refresh nahi hoga!");
    return false;
  });

  globalShortcut.register("Control+R", () => {
    console.log("Ctrl+R blocked");
    return false;
  });

  globalShortcut.register("Command+R", () => {
    console.log("Cmd+R blocked (Mac)");
    return false;
  });

  globalShortcut.register("Control+Shift+R", () => {
    console.log("Developer refresh!");
    mainWindow?.reload();
  });

  globalShortcut.register("Control+Shift+F5", () => {
    console.log("Force refresh (bypass cache)");
    mainWindow?.webContents.reloadIgnoringCache();
  });
  const shortcuts = [
    { key: "Control+1", route: "/" },
    { key: "Control+2", route: "/pos" },
    { key: "Control+3", route: "/inventory" },
    { key: "Control+4", route: "/inventory/add" },
    { key: "Control+5", route: "/customers" },
    { key: "Control+6", route: "/invoice/history" },
    { key: "Control+7", route: "/settings" },
    { key: "Control+8", route: "/pricing" },
    { key: "Control+9", route: "/support" },
    { key: "Control+Shift+R", action: "reload" },
    { key: "Control+Shift+Q", action: "quit" },
  ];

  shortcuts.forEach(({ key, route, action }) => {
    globalShortcut.register(key, () => {
      if (action === "reload") {
        mainWindow.reload();
      } else if (action === "quit") {
        app.quit();
      } else {
        // Renderer ko batao: "Is route pe ja!"
        mainWindow.webContents.send("navigate-to", route);
      }
    });
  });
  await initializeDatabase();
  setupIpcHandlers();
  createWindow();
});

